    //         Math.max(0, (row.baseAllocation || 3.0) - (row.allocationToSubjectCoordinationTeam || 0.5))
    //     );

    //     const increaseOfBaseAllocation = lecturerAllocations.reduce((sum, current) => sum + current, 0);

    //     const sumCoordTeamAllocation = deliveries.reduce((sum, row) => sum + (row.allocationToSubjectCoordinationTeam || 0.5), 0);

    //     let subjectCoordinatorAllocation = 0;
