    //     const baseAlloc = editingRow.baseAllocation || 3.0;

    //     // Validation
    //     if (isNaN(numericValue) || numericValue < 0 || numericValue > baseAlloc) {
    //         setError(`Value must be between 0 and ${baseAlloc}.`);
    //         return;
    //     }

